/* eslint-disable no-invalid-this */

'use strict';

// MODULES //

var logger = require( 'debug' );
var isNumberArray = require( '@stdlib/assert/is-number-array' ).primitives;
var isNumber = require( '@stdlib/assert/is-number' ).isPrimitive;
var hasEqualValues = require( '@stdlib/array/base/assert/has-equal-values' );
var min = require( '@stdlib/math/base/special/fast/min' );
var copy = require( '@stdlib/array/base/copy' );
var join = require( '@stdlib/array/base/join' );
var format = require( '@stdlib/string/format' );
var changeEvent = require( './../change_event.js' );
var prop = require( './properties.js' );


// VARIABLES //

var debug = logger( 'line-chart:set:'+prop.name );


// MAIN //

/**
* Sets line opacities.
*
* @private
* @param {(Array<number>|number)} value - input value
* @throws {TypeError} must be a number or an array of numbers
* @returns {void}
*/
function set( value ) {
	var values;
	var isNum;
	var marks;
	var N;
	var i;

	isNum = isNumber( value );
	if ( !isNum && !isNumberArray( value ) ) {
		throw new TypeError( format( 'invalid assignment. `%s` must be a number or an array of numbers. Value: `%s`.', prop.name, value ) );
	}
	if ( isNum ) {
		value = [ value ];
	}
	if ( !hasEqualValues( value, this[ prop.private ] ) ) {
		debug( 'Current value: [%s]. New value: [%s].', join( this[ prop.private ], ', ' ), join( value, ', ' ) );
		values = copy( value );
		marks = this.config.marks;
		N = min( marks.length, values.length );
		for ( i = 0; i < N; i++ ) {
			marks[ i ].encoding.update.strokeWidth.value = values[ i ];
		}
		this[ prop.private ] = values;
		this.emit( 'change', changeEvent( prop.name ) );
	}
}


// EXPORTS //

module.exports = set;
